{
  "aktywnosci": [
    {
      "tytul": "Leśne skarby w kąciku przyrody – badanie darów jesieni",
      "opis": "Nauczyciel przygotowuje tacę ze zgromadzonymi darami lasu: szyszkami, żołędziami, kawałkami kory i suchymi liśćmi. Dzieci oglądają leśne znaleziska, dotykają ich, porównują faktury i wielkości oraz dzielą je na grupy według rodzaju. Na zakończenie wspólnie układają ze skarbów jesienną wystawę na półce w sali."
    },
    {
      "tytul": "Wiewiórki zbierają zapasy – zabawa ruchowa z elementem liczenia",
      "opis": "Nauczyciel rozkłada na dywanie obręcze gimnastyczne symbolizujące dziuple, a na środku sali rozsypuje kasztany i szyszki. Dzieci, naśladując wiewiórki, biegają swobodnie w rytm wygrywany na tamburynie. Na przerwę w muzyce każde dziecko podnosi jeden leśny skarb i zanosi go do najbliższej dziupli, a potem wspólnie przeliczają zebrane zapasy."
    },
    {
      "tytul": "Kolorowy las – stemplowanie jesiennymi liśćmi",
      "opis": "Nauczyciel przygotowuje farby plakatowe w odcieniach żółci, czerwieni i brązu, duże arkusze papieru oraz świeże liście o wyraźnych żyłkach. Dzieci malują pędzelkiem spodnią stronę liścia, a następnie ostrożnie dociskają go dłońmi do papieru, tworząc barwne odbitki drzew. Nauczyciel wspiera najmłodszych w dokładnym dociskaniu liści, by powstały wyraźne leśne wzory."
    }
  ]
}
